/* NEO AI — legal modal deep link.

   Research pages are separate documents and cannot host the landing page's
   legal modal, whose content lives inside app-sections.min.js. Duplicating
   that text into a second file would create two sources of truth for a legal
   notice, which is the one kind of drift that must not be allowed.

   Instead the research footer links to /?legal=privacy|terms|cookies, and this
   file opens the existing modal on arrival by dispatching a click on the
   element the existing handler already listens for. No legal text is
   duplicated, and app-sections.min.js is not modified.

   Placed last in the landing page's script list so the delegated [data-legal]
   handler in app-sections.min.js is already bound. Both are `defer`, so
   document order is execution order. */
(function () {
  'use strict';
  var m = /[?&]legal=(privacy|terms|cookies)\b/.exec(location.search);
  if (!m) return;
  var open = function () {
    var el = document.querySelector('[data-legal="' + m[1] + '"]');
    if (!el) return;
    el.click();
    /* Remove the parameter so a reload, a share or a crawl does not carry a
       state-bearing URL. The canonical stays the clean homepage. */
    if (history.replaceState) {
      history.replaceState(null, '', location.pathname + location.hash);
    }
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      setTimeout(open, 0);
    });
  } else {
    setTimeout(open, 0);
  }
})();
